def shortest_path(graph, source, target):
    import heapq

    def bfs(graph, source, target):
        visited = set()
        queue = deque([(source, [])])
        while queue:
            current, path = queue.popleft()
            if current == target:
                return path + [current]
            if current not in visited:
                visited.add(current)
                for neighbor, weight in graph.get(current, []):
                    if neighbor not in visited:
                        queue.append((neighbor, path + [current]))
        return None

    def dfs(graph, source, target):
        visited = set()
        path_stack = [(source, [])]
        while path_stack:
            current, path = path_stack.pop()
            if current == target:
                return path + [current]
            if current not in visited:
                visited.add(current)
                for neighbor, weight in graph.get(current, []):
                    if neighbor not in visited:
                        path_stack.append((neighbor, path + [current]))
        return None

    def dijkstra(graph, source, target):
        visited = set()
        distances = {node: float('inf') for node in graph}
        distances[source] = 0
        queue = [(0, source)]
        while queue:
            current_distance, current = heapq.heappop(queue)
            if current == target:
                return (current_distance, [current] + path)
            if current not in visited:
                visited.add(current)
                for neighbor, weight in graph.get(current, []):
                    tentative_distance = current_distance + weight
                    if tentative_distance < distances[neighbor]:
                        distances[neighbor] = tentative_distance
                        heapq.heappush(queue, (tentative_distance, neighbor))
        return (float('inf'), None)
    bfs_path = bfs(graph, source, target)
    dfs_path = dfs(graph, source, target)
    for path in [bfs_path, dfs_path]:
        if path:
            return (distances[target], path)
    dijkstra_path = dijkstra(graph, source, target)
    if dijkstra_path[0] != float('inf'):
        return dijkstra_path
    return (float('inf'), None)

